class Solution {
  public int numPoints(int[][] points, int r) {
    int best = Math.min(1, points.length);
    double diameter = 2.0 * r;
    for (int i = 0; i < points.length; i++)
      for (int j = i + 1; j < points.length; j++) {
        double dx = points[j][0] - points[i][0], dy = points[j][1] - points[i][1];
        double d = Math.hypot(dx, dy);
        if (d > diameter + 1e-9) continue;
        if (d < 1e-12) {
          int count = 0;
          for (int[] p : points)
            if (Math.hypot(p[0] - points[i][0], p[1] - points[i][1]) <= r + 1e-7) count++;
          best = Math.max(best, count);
          continue;
        }
        double mx = (points[i][0] + points[j][0]) / 2.0, my = (points[i][1] + points[j][1]) / 2.0;
        double h = Math.sqrt(Math.max(0, r * (double) r - d * d / 4));
        double ux = -dy / d, uy = dx / d;
        for (int sign = -1; sign <= 1; sign++) {
          double cx = mx + sign * h * ux, cy = my + sign * h * uy;
          int count = 0;
          for (int[] p : points) if (Math.hypot(p[0] - cx, p[1] - cy) <= r + 1e-7) count++;
          best = Math.max(best, count);
        }
      }
    return best;
  }
}
